'use strict';

let facilitator=sessionStorage.getItem('ecolelien-facilitator')==='1';
let pilotLanguage=localStorage.getItem('ecolelien-language')||'fr';
function toggleFacilitator(){facilitator=!facilitator;sessionStorage.setItem('ecolelien-facilitator',facilitator?'1':'0');if(page==='Projet & pilote')page='Accueil';render()}
function toggleLanguage(){pilotLanguage=pilotLanguage==='fr'?'wo':'fr';localStorage.setItem('ecolelien-language',pilotLanguage);render()}
function isoDay(offset=0){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Dakar',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const val=k=>parts.find(p=>p.type===k).value;const d=new Date(val('year')+'-'+val('month')+'-'+val('day')+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+offset);return d.toISOString().slice(0,10)}
function displayDay(value){return new Intl.DateTimeFormat('fr-SN',{day:'numeric',month:'long',timeZone:'Africa/Dakar'}).format(new Date(value+'T12:00:00Z'))}
const svgPaths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',message:'M3 4h18v13H8l-5 4Z M3 5l9 7 9-7',bell:'M6 16V9a6 6 0 0 1 12 0v7l2 2H4Z M9 21h6',trash:'M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',users:'M8 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3a6 6 0 0 1 12 0v3 M17 4a4 4 0 0 1 0 8 M17 15a5 5 0 0 1 5 5v1',file:'M5 3h9l5 5v13H5Z M14 3v6h5 M8 13h8 M8 17h6',calendar:'M3 5h18v16H3Z M7 2v6 M17 2v6 M3 10h18 M7 14h2 M13 14h2',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l4 2',check:'M4 12l5 5L20 6',grade:'M4 20 10 4l6 16 M7 14h7 M17 6h6 M20 3v6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',menu:'M4 6h16 M4 12h16 M4 18h16',card:'M3 5h18v14H3Z M8 9a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M5 16h6 M14 9h4 M14 13h4',edit:'m4 16 12-12 4 4L8 20H4Z M14 6l4 4',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',wallet:'M3 5h17v15H3Z M15 10h7v6h-7Z M18 13h1',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 9a3 3 0 1 1 4 3l-1 2 M12 17h.01',arrow:'M4 12h16 M14 6l6 6-6 6',school:'M3 9 12 3l9 6v12H3Z M9 21v-7h6v7 M6 11h2 M16 11h2',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11'};
function icon(name){return '<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(svgPaths[name]||svgPaths.file)+'"/></svg>'}
function symbolIcon(s){if(String(s).startsWith('<svg'))return s;return icon({'⌂':'home','✉':'message','♧':'users','♙':'users','♜':'trash','▱':'file','▤':'file','▦':'calendar','◷':'clock','✓':'check','A⁺':'grade','⚙':'settings','☷':'menu','☰':'menu','▣':'card','✎':'edit','★':'star','◈':'wallet','◇':'help','↗':'arrow','?':'help','◐':'moon'}[s]||'file')}
function navigationPages(r){return roles[r].pages.filter(p=>facilitator||p!=='Projet & pilote')}

const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('fr-SN').format(n)+' F CFA';
const roles={parent:{label:'Parent',name:'Fatou Fall',initials:'FF',detail:'Awa · CM2 et Ibrahima · 4e',color:'green',intro:'Suivez vos enfants, échangez avec l’école et retrouvez les actions importantes.',pages:['Accueil','Actualités','Messages','Présences','Scolarité','Documents','Formulaires','Calendrier','Préférences','Projet & pilote']},student:{label:'Élève',name:'Ibrahima Fall',initials:'IF',detail:'4e A · Collège',intro:'Vos cours, vos devoirs et vos enseignants, dans un espace personnel.',pages:['Accueil','Devoirs','Emploi du temps','Messages','Documents','Calendrier','Préférences','Projet & pilote']},teacher:{label:'Enseignant',name:'Marième Diop',initials:'MD',detail:'Enseignante titulaire · CM2 A',intro:'Gérez votre classe, faites l’appel et accompagnez les familles.',pages:['Accueil','Ma classe','Présences','Devoirs','Actualités','Messages','Formulaires','Calendrier','Préférences','Projet & pilote']},admin:{label:'Direction',name:'Cheikh Ba',initials:'CB',detail:'Directeur · Groupe scolaire pilote Malika Plage',intro:'Pilotez l’école, les dossiers, les finances et la communication.',pages:['Accueil','Communauté','Présences','Scolarité','Actualités','Formulaires','Activité','Préférences','Projet & pilote']}};
const icons={'Accueil':'⌂','Actualités':'▤','Messages':'✉','Présences':'✓','Scolarité':'◈','Documents':'▱','Formulaires':'☷','Calendrier':'▦','Préférences':'⚙','Projet & pilote':'◇','Devoirs':'✎','Emploi du temps':'◷','Ma classe':'♧','Communauté':'♧','Activité':'↗'};
for(const k of Object.keys(icons))icons[k]=symbolIcon(icons[k]);
const initial=()=>({ack:[],bookmarks:[],messages:[],attendance:{},absence:{status:'À justifier',reason:'',note:''},payments:(typeof feeSeed==='function'?feeSeed():[{amount:45000,method:'Espèces',date:'5 octobre',id:'DEMO-001',student:'awa'}]),feeRevision:(typeof feeSeed==='function'?1:0),senegalRevision:1,homework:[{id:'hw1',student:'ibrahima',subject:'Mathématiques',title:'Équations et pourcentages',description:'Résoudre 2x + 5 = 17. Calculer 15 % de 240.',due:isoDay(1)},{id:'hw2',student:'ibrahima',subject:'Français',title:'Lecture et résumé',description:'Lire le texte donné en classe et rédiger un résumé de 10 lignes.',due:isoDay(2)},{id:'hw3',student:'awa',subject:'Mathématiques',title:'Fractions simples',description:'Exercices 1 et 2 sur la fiche distribuée en classe.',due:isoDay(1)}],completed:[],posts:[{id:'p1',title:'Fortes pluies : fermeture le '+displayDay(isoDay()),body:'Les cours sont suspendus le '+displayDay(isoDay())+'. La direction confirmera la reprise prévue le '+displayDay(isoDay(1))+'. Merci de confirmer la réception.',target:'all',author:'Direction',type:'urgent',date:displayDay(isoDay(-1)),ack:true},{id:'p2',title:'Rencontres parents et enseignants',body:'Les rendez-vous pour les parents de CM2 se tiendront le '+displayDay(isoDay(3))+'. Réservez votre créneau dans le calendrier.',target:'awa',author:'Marième Diop',type:'action',date:displayDay(isoDay(-2))},{id:'p3',title:'La fiche de mathématiques est disponible',body:'La fiche sur les équations et les pourcentages est disponible pour les élèves de 4e.',target:'ibrahima',author:'M. Ndiaye',type:'class',date:displayDay(isoDay(-1))}],forms:[{id:'f1',title:'Autorisation de sortie pédagogique',student:'awa',body:'Sortie au musée le '+displayDay(isoDay(8))+', de 9 h à 12 h. Départ et retour à l’école, accompagnement par l’équipe enseignante.',deadline:isoDay(5)}],responses:{},booking:'',contacts:[{id:'c1',name:'Fatou Fall',relationship:'Parent autorisé',student:'Awa et Ibrahima',access:'Suivi scolaire et frais',phone:'+221 77 000 00 01'},{id:'c2',name:'Ousmane Fall',relationship:'Payeur',student:'Awa et Ibrahima',access:'Frais et reçus uniquement',phone:'+221 77 000 00 02'}],preferences:{parent:{channel:'Application',digest:true,quiet:true},student:{channel:'Application',digest:true,quiet:true},teacher:{channel:'Application',digest:true,quiet:true},admin:{channel:'Application',digest:true,quiet:true}},activities:[],demoDay:isoDay()});
let db;try{db=JSON.parse(localStorage.getItem('ecolelien-v3'))}catch{}db=db||initial();let account=sessionStorage.getItem('ecolelien-v3-account'),page='Accueil',child='all',postFilter='all',conversation='family';
const students={awa:{name:'Awa Fall',short:'Awa',class:'CM2 A',initials:'AF'},ibrahima:{name:'Ibrahima Fall',short:'Ibrahima',class:'4e A',initials:'IF'}};const roster=[{id:'awa',name:'Awa Fall'},{id:'moussa',name:'Moussa Ba'},{id:'aminata',name:'Aminata Sow'},{id:'omar',name:'Omar Sarr'},...Array.from({length:56},(_,i)=>({id:'demo-'+(i+5),name:['Fatou','Mamadou','Aïssatou','Cheikh','Ndeye','Abdou','Seynabou','Ibrahima'][i%8]+' '+['Diop','Ndiaye','Sow','Sarr','Fall','Ba','Faye'][Math.floor(i/8)]+' · '+String(i+5).padStart(2,'0')}))];
function persist(){localStorage.setItem('ecolelien-v3',JSON.stringify(db))}function log(text){db.activities.unshift({text,author:roles[account]?.name||'Démo',date:'À l’instant'});persist()}function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,3500)}function modal(h){$('#modal').innerHTML=h;$('#modal').showModal()}function closeModal(){$('#modal').close()}function fieldsEnd(label='Enregistrer'){return `<div class="actions"><button type="button" onclick="closeModal()">Annuler</button><button class="primary">${label}</button></div>`}function permitted(...r){return r.includes(account)}function go(p){if(!roles[account]?.pages.includes(p)||(p==='Projet & pilote'&&!facilitator)){notify('Cet écran est réservé à un autre compte de démonstration.');return}page=p;render();window.scrollTo(0,0)}function login(r){if(!roles[r])return;account=r;page='Accueil';conversation=r==='student'?'student':'family';sessionStorage.setItem('ecolelien-v3-account',r);render()}function logout(){account=null;sessionStorage.removeItem('ecolelien-v3-account');render()}function resetDemo(){modal(`<h2>Recommencer la démonstration</h2><p>Les messages, les réponses, les réservations et les versements simulés de ce navigateur seront effacés.</p><div class="actions"><button onclick="closeModal()">Conserver</button><button class="danger" onclick="db=initial();persist();closeModal();logout()">Réinitialiser</button></div>`)}
function avatar(i){return `<span class="avatar">${i}</span>`}function card(t,b,extra=''){return `<section class="card"><div class="card-head"><h2>${t}</h2>${extra}</div>${b}</section>`}function button(t,p,c=''){return `<button class="${c}" onclick="go('${p}')">${t}</button>`}function head(t,s,action=''){return `<div class="page-head"><div><h1>${t}</h1><p class="subtitle">${s}</p></div>${action}</div>`}function stats(a){return `<div class="stats">${a.map(([label,note,sub,icon])=>`<div class="stat"><div class="label">${label}<span class="icon">${symbolIcon(icon||'◈')}</span></div><strong>${note}</strong><small>${sub}</small></div>`).join('')}</div>`}function quick(a){return `<div class="quick">${a.map(([t,p])=>`<button onclick="go('${p}')"><span>${icons[p]}</span>${t}</button>`).join('')}</div>`}function nameTarget(t){return t==='all'?'Toute l’école':students[t]?.short+' · '+students[t]?.class}function tag(t){return `<span class="tag ${t==='urgent'?'amber':t==='action'?'blue':''}">${t==='urgent'?'Prioritaire':t==='action'?'À faire':t==='class'?'Classe':'École'}</span>`}function relevantPosts(){return db.posts.filter(p=>account==='student'?['all','ibrahima'].includes(p.target):account==='teacher'?['all','awa'].includes(p.target):child==='all'||['all',child].includes(p.target))}function children(){return `<div class="children">${[['all','Tous mes enfants','2 enfants'],['awa','Awa','CM2 A'],['ibrahima','Ibrahima','4e A']].map(([id,n,c])=>`<button class="child ${child===id?'active':''}" onclick="child='${id}';render()">${avatar(id==='all'?'2':students[id].initials)}<div>${n}<small>${c}</small></div></button>`).join('')}</div>`}
function confirmNotice(id){if(account!=='parent'||db.ack.includes(id))return;db.ack.push(id);db.receiptChannels=db.receiptChannels||{};db.receiptChannels[id]='Application';log('Famille Fall : réception de l’annonce confirmée');render();notify('La direction peut maintenant voir votre confirmation.')}function toggleBookmark(id){db.bookmarks=db.bookmarks.includes(id)?db.bookmarks.filter(x=>x!==id):[...db.bookmarks,id];persist();render()}
function postHTML(p){let actionable=p.ack&&account==='parent';return `<article class="post"><div class="post-head"><div>${tag(p.type)}<h3>${esc(p.title)}</h3></div><button class="ghost" aria-label="Enregistrer l’annonce" onclick="toggleBookmark('${p.id}')">${db.bookmarks.includes(p.id)?'★':'☆'}</button></div><div class="meta">${esc(p.author)} · ${esc(p.date)} · ${nameTarget(p.target)}</div><p>${esc(p.body)}</p><div class="post-footer">${actionable?`<button class="${db.ack.includes(p.id)?'':'primary'}" onclick="confirmNotice('${p.id}')" ${db.ack.includes(p.id)?'disabled':''}>${db.ack.includes(p.id)?'✓ Réception confirmée':'Confirmer la réception'}</button>`:p.ack&&permitted('admin','teacher')?`<span class="tag">Famille Fall : ${db.ack.includes(p.id)?'confirmé':'en attente'}</span>`:''}${p.id==='p2'&&account==='parent'?button('Réserver un créneau','Calendrier'):''}${p.id==='p3'&&permitted('parent','student')?button('Voir la fiche','Documents'):''}</div></article>`}
function home(){if(account==='parent')return head('Bonjour, Fatou 👋','Ce qui compte pour vos enfants, aujourd’hui.')+children()+hero('Information de la direction','Fermeture exceptionnelle le '+displayDay(isoDay()),'Fortes pluies : confirmez la réception de l’annonce.',db.ack.includes('p1')?'✓ Confirmé':'J’ai reçu l’information',"confirmNotice('p1')")+stats([['Mes enfants','2','CM2 A et 4e A','♧'],['Actions',String((db.ack.includes('p1')?0:1)+(db.responses.f1?0:1)),'À traiter','✓'],['Absences','1',db.absence.status,'◷'],['Solde',money(balance()),'Échéance : '+(typeof feeDueDay==='function'?feeDueDay():displayDay(isoDay(6))),'◈']])+`<div class="grid">${card('Les dernières nouvelles',relevantPosts().slice(0,2).map(postHTML).join(''),button('Tout voir','Actualités','ghost small'))}<div>${card('Vos raccourcis',quick([['Messages','Messages'],['Justifier','Présences'],['Payer','Scolarité'],['Documents','Documents'],['Autorisation','Formulaires'],['Rendez-vous','Calendrier']]))}${card('À votre agenda',eventRows())}</div></div>`;
if(account==='student')return head('Bonjour, Ibrahima 👋','4e A · Votre semaine, à votre rythme.')+hero('Mon espace élève','Prêt pour le prochain cours ?','Retrouvez vos devoirs et téléchargez vos ressources pour la maison.','Mes devoirs',"go('Devoirs')")+stats([['Mes devoirs',String(db.homework.filter(h=>h.student==='ibrahima'&&!db.completed.includes(h.id)).length),'À préparer','✎'],['Cours','5','Journée type','◷'],['Ressources','2','Téléchargeables','▱'],['Messages',String(db.messages.filter(m=>m.thread==='student').length),'Échanges de démonstration','✉']])+`<div class="grid">${card('Mes devoirs à venir',taskRows('ibrahima'),button('Tout voir','Devoirs','ghost small'))}<div>${card('Mes outils',quick([['Planning','Emploi du temps'],['Enseignants','Messages'],['Ressources','Documents']]))}${card('Actualités de ma classe',relevantPosts().slice(0,1).map(postHTML).join(''))}</div></div>`;
if(account==='teacher')return head('Bonjour, Marième 👋','CM2 A · Une journée organisée, des familles accompagnées.')+hero('Ma classe','Votre classe, prête pour la journée','Faites l’appel, publiez vos devoirs et répondez aux familles.','Faire l’appel',"go('Présences')")+stats([['Mes élèves','60','CM2 A','♧'],['Appel',(db.attendanceSavedDate===isoDay()?'60 / 60':'À faire'),'Présences renseignées','✓'],['Devoirs',String(db.homework.filter(h=>h.student==='awa').length),'Pour le CM2','✎'],['Messages',String(db.messages.filter(m=>m.thread==='family').length),'Échanges avec les familles','✉']])+`<div class="grid">${card('Mes élèves',roster.slice(0,4).map(r=>`<div class="row"><b>${r.name}</b><span>CM2 A</span></div>`).join(''),button('Ma classe','Ma classe','ghost small'))}<div>${card('Actions de la classe',quick([['Appel','Présences'],['Devoirs','Devoirs'],['Annonces','Actualités'],['Messages','Messages'],['Formulaires','Formulaires'],['Agenda','Calendrier']]))}${card('Suivi des familles',`<p>Annonce de fermeture : <span class="tag">${db.ack.includes('p1')?'Famille Fall : confirmée':'Famille Fall : en attente'}</span></p><p class="help">Les indicateurs de cette démo concernent la famille fictive, pas les 60 élèves.</p>`)}</div></div>`;
return head('Vue d’ensemble de l’école','Cheikh Ba · Direction · Année scolaire 2026 / 2027.')+hero('Pilotage de l’établissement','Une école connectée à ses familles','Vérifiez les demandes, les dossiers et les dernières actions.','Examiner les absences',"go('Présences')")+stats([['Élèves','486','Effectif fictif','♧'],['Confirmation',db.ack.includes('p1')?'1 / 1':'0 / 1','Famille de démonstration','✓'],['Justifications',db.absence.status==='Transmise'?'1':'0','À vérifier','▤'],['Encaissements',money(db.payments.reduce((s,p)=>s+p.amount,0)),'Famille Fall, montant simulé','◈']])+`<div class="grid">${card('Actions de la direction',quick([['Responsables','Communauté'],['Assiduité','Présences'],['Scolarité','Scolarité'],['Annonces','Actualités'],['Formulaires','Formulaires'],['Activité','Activité']]))}<div>${card('Dernières actions',activityRows(4))}${card('Réponses aux autorisations',`<p>Sortie pédagogique · Awa Fall</p><span class="tag ${db.responses.f1?'':'amber'}">${db.responses.f1?esc(db.responses.f1.choice):'Réponse attendue'}</span>`)}</div></div>`}
function hero(e,t,s,b,a){return `<section class="hero"><div><span class="eyebrow">${e}</span><h2>${t}</h2><p>${s}</p></div><button onclick="${a}">${b}</button></section>`}
function news(){return head('Actualités',permitted('admin','teacher')?'Publiez au bon groupe et suivez les confirmations.':'Des informations classées, faciles à retrouver.',permitted('admin','teacher')?'<button class="primary small" onclick="composePost()">+ Publier</button>':'')+(account==='parent'?children():'')+`<div class="toolbar"><input id="post-search" type="search" placeholder="Rechercher une annonce" aria-label="Rechercher une annonce" oninput="filterNews()"></div><div class="tabs">${[['all','Toutes'],['urgent','Prioritaires'],['saved','Enregistrées']].map(([id,n])=>`<button class="${postFilter===id?'active':''}" onclick="postFilter='${id}';render()">${n}</button>`).join('')}</div>`+card('Le fil de l’école','<div id="post-list">'+filteredPosts().map(postHTML).join('')+'</div>')}
function filteredPosts(q=''){return relevantPosts().filter(p=>(postFilter==='all'||postFilter==='urgent'&&p.type==='urgent'||postFilter==='saved'&&db.bookmarks.includes(p.id))&&(p.title+' '+p.body).toLowerCase().includes(q.toLowerCase()))}function filterNews(){$('#post-list').innerHTML=filteredPosts($('#post-search').value).map(postHTML).join('')||'<p class="empty">Aucun résultat.</p>'}
function composePost(){if(!permitted('admin','teacher'))return;modal(`<h2>Nouvelle annonce</h2><form onsubmit="publishPost(event)"><label>Titre<input id="post-title" required maxlength="120" placeholder="Une information claire"></label><label>Destinataires<select id="post-target">${account==='admin'?'<option value="all">Toute l’école</option>':''}<option value="awa">CM2 A</option>${account==='admin'?'<option value="ibrahima">4e A</option>':''}</select></label><label>Message<textarea id="post-body" required maxlength="3000"></textarea></label><label class="checkline"><input id="post-ack" type="checkbox"> Demander une confirmation explicite</label><p class="help">Publication simulée, visible dans les comptes concernés.</p>${fieldsEnd('Publier')}</form>`)}function publishPost(e){e.preventDefault();if(!permitted('admin','teacher'))return;db.posts.unshift({id:'p'+Date.now(),title:$('#post-title').value,body:$('#post-body').value,target:$('#post-target').value,author:roles[account].name,type:$('#post-ack').checked?'action':'class',ack:$('#post-ack').checked,date:'À l’instant'});log('Annonce publiée : '+$('#post-title').value);closeModal();render();notify('Annonce publiée dans les espaces concernés. Aucun envoi extérieur.')}
function taskRows(student){const list=db.homework.filter(h=>h.student===student);return list.map(h=>`<div class="row start"><div class="body"><span class="tag blue">${esc(h.subject)}</span><h3 class="${db.completed.includes(h.id)?'taskdone':''}" style="margin-top:8px">${esc(h.title)}</h3><div class="meta">Pour le ${esc(h.due)} · ${nameTarget(h.student)}</div><p class="help">${esc(h.description)}</p><button class="small" onclick="taskDetail('${h.id}')">Ouvrir le devoir</button></div>${account==='student'?`<div class="checkline"><input aria-label="Marquer ${esc(h.title)} terminé" type="checkbox" ${db.completed.includes(h.id)?'checked':''} onchange="completeTask('${h.id}')"></div>`:''}</div>`).join('')||'<p class="empty">Aucun devoir pour le moment.</p>'}
function completeTask(id){if(account!=='student')return;db.completed=db.completed.includes(id)?db.completed.filter(x=>x!==id):[...db.completed,id];persist();render()}function taskDetail(id){const h=db.homework.find(h=>h.id===id);if(!h)return;modal(`<span class="tag blue">${esc(h.subject)}</span><h2 style="margin-top:15px">${esc(h.title)}</h2><p>${esc(h.description)}</p><p class="meta">À préparer pour le ${esc(h.due)}</p><button class="primary" onclick="downloadTask('${h.id}')">Télécharger la fiche</button><div class="actions"><button onclick="closeModal()">Fermer</button></div>`)}function downloadTask(id){let h=db.homework.find(h=>h.id===id);download('Devoir_'+h.student+'.txt','RESSOURCE DE DÉMONSTRATION\n'+h.title+'\n'+h.description+'\nÉchéance : '+h.due)}function homework(){return head(account==='student'?'Mes devoirs':'Devoirs de ma classe',account==='student'?'Une liste claire pour préparer votre semaine.':'Publiez les travaux destinés aux élèves de CM2.',account==='teacher'?'<button class="primary small" onclick="addHomework()">+ Ajouter</button>':'')+card(account==='student'?'4e A':'CM2 A',taskRows(account==='student'?'ibrahima':'awa'))}
function addHomework(){if(account!=='teacher')return;modal(`<h2>Publier un devoir</h2><form onsubmit="saveHomework(event)"><label>Titre<input id="hw-title" required></label><label>Matière<select id="hw-subject"><option>Mathématiques</option><option>Français</option><option>Sciences</option></select></label><label>Date limite<input id="hw-due" type="date" required value="2026-10-16"></label><label>Consignes<textarea id="hw-description" required></textarea></label>${fieldsEnd('Publier')}</form>`)}function saveHomework(e){e.preventDefault();if(account!=='teacher')return;db.homework.unshift({id:'hw'+Date.now(),student:'awa',title:$('#hw-title').value,subject:$('#hw-subject').value,due:$('#hw-due').value,description:$('#hw-description').value});log('Devoir CM2 publié : '+$('#hw-title').value);closeModal();render();notify('Devoir ajouté à la classe. La famille peut télécharger la fiche.')}
function chats(){const threads=account==='student'?[['student','M. Ndiaye','Mathématiques · Ibrahima · 4e A']]:[['family',account==='teacher'?'Fatou Fall':'Marième Diop','Awa · CM2 A'],...(account==='parent'?[['ibrahima-family','M. Ndiaye','Ibrahima · 4e A']]:[]),['school','Secrétariat','Surveillance générale · Famille Fall']];if(!threads.some(t=>t[0]===conversation))conversation=threads[0][0];const current=threads.find(t=>t[0]===conversation);return head(account==='teacher'?'Messages des familles':account==='student'?'Mes enseignants':'Messages','Par enfant et enseignant. Annonces ciblées, confirmation explicite et reçus disponibles.')+`<div class="grid equal">${card('Conversations',threads.map(([id,n,d])=>`<button class="conversation ${conversation===id?'active':''}" onclick="conversation='${id}';render()"><h3>${n}</h3><span class="meta">${d}</span></button>`).join('')+'<div class="notice">Horaires de réponse : lundi à vendredi, 8 h à 17 h. Pour une urgence, contactez le secrétariat.</div>')}${card(esc(current[1]),`<div class="meta">${current[2]}</div><div class="chat-scroll"><div class="bubble"><small>Équipe pédagogique · Démonstration</small>${conversation==='student'?'Bonjour Ibrahima, la fiche est disponible dans tes documents.':conversation==='family'?'Bonjour, les rendez-vous sont ouverts dans le calendrier.':'Bonjour, vous pouvez envoyer votre question au surveillant général.'}</div>${db.messages.filter(m=>m.thread===conversation).map(m=>`<div class="bubble ${m.from===account?'mine':''}"><small>${esc(roles[m.from].name)} · ${esc(m.time)}</small>${esc(m.text)}</div>`).join('')}</div><form onsubmit="sendMessage(event)"><label>Votre message<textarea id="chat-message" required maxlength="2000" placeholder="Écrivez votre message…"></textarea></label><button class="primary">Envoyer</button></form><p class="help">Messages simulés dans ce navigateur, aucun envoi réel.</p>`)}</div>`}
function sendMessage(e){e.preventDefault();if(!permitted('parent','student','teacher'))return;db.messages.push({id:Date.now(),from:account,thread:conversation,text:$('#chat-message').value,time:'À l’instant'});log('Message dans la conversation '+(conversation==='family'?'CM2 A':conversation==='student'?'4e A':'secrétariat'));render();notify(conversation==='family'?'Message ajouté. Le compte parent ou enseignante peut le consulter.':'Message ajouté à la démonstration.')}
function rosterRows(){return roster.map(r=>`<div class="row">${avatar(r.name.split(' ').map(x=>x[0]).join(''))}<div class="body"><h3>${r.name}</h3><div class="meta">CM2 A · ${db.attendance[r.id]||'Appel non renseigné'}</div></div><button class="small" onclick="studentDetail('${r.id}')">Dossier</button></div>`).join('')}
function studentDetail(id){if(!permitted('teacher','admin'))return;const r=roster.find(x=>x.id===id);modal(`<h2>${r.name}</h2><span class="tag">CM2 A · Élève fictif</span><p>Présence : ${esc(db.attendance[id]||'Non renseignée')}</p>${id==='awa'?'<p>Responsable autorisé : Fatou Fall<br>Payeur : Ousmane Fall</p>':'<p class="help">Le dossier détaillé n’est pas renseigné dans cet échantillon.</p>'}<div class="actions"><button onclick="closeModal()">Fermer</button></div>`)}function classroom(){return head('Ma classe','CM2 A · 60 élèves')+card('Liste des élèves',rosterRows())+`<div class="notice">Les dossiers accessibles correspondent uniquement à la classe attribuée à l’enseignante.</div>`}
function attendance(){if(account==='teacher')return attendanceClass();
if(account==='admin')return head('Vie scolaire','Suivez l’appel et validez les demandes de justification.')+`<div class="grid equal">${card('Justification à examiner',`<span class="tag ${db.absence.status==='Transmise'?'amber':''}">${esc(db.absence.status)}</span><h3 style="margin-top:15px">Ibrahima Fall · 4e A</h3><p>Absence du 12 octobre, 8 h à 10 h.</p><p>Motif : ${esc(db.absence.reason||'Non communiqué')}</p><p class="help">${esc(db.absence.note)}</p>${db.absence.status==='Transmise'?'<div class="pillrow"><button class="primary" onclick="validateAbsence(true)">Valider</button><button onclick="validateAbsence(false)">Demander une précision</button></div>':'<p class="help">Le parent peut transmettre une justification depuis son espace.</p>'}`)}${card('Dernier appel · CM2 A',roster.map(r=>`<div class="row"><b>${r.name}</b><span class="tag">${esc(db.attendance[r.id]||'Non renseigné')}</span></div>`).join(''))}</div>`;
return head('Présences de mes enfants','Un historique clair et des justifications transmises à l’école.')+children()+(child!=='awa'?card('Ibrahima · 4e A',`<div class="row start"><div class="body"><span class="tag amber">${esc(db.absence.status)}</span><h3 style="margin-top:13px">Absence du 12 octobre</h3><p>8 h à 10 h · Mathématiques</p>${db.absence.reason?'<p class="help">Motif transmis : '+esc(db.absence.reason)+'</p>':''}</div><button class="primary small" onclick="justifyAbsence()">${db.absence.status==='À justifier'?'Justifier':'Voir / compléter'}</button></div><p class="help">Le surveillant général vérifie la demande. Transmettre ne signifie pas automatiquement valider.</p>`):'')+(child!=='ibrahima'?card('Awa · CM2 A',`<p>Appel du ${db.attendanceSavedDate?displayDay(db.attendanceSavedDate):displayDay(isoDay())} : <span class="tag">${esc(db.attendance.awa||'Pas encore renseigné')}</span></p>`):'')}
let attendanceDraft=null,attendanceDraftDate='',attendanceStarted=0,attendanceSearch='';
function beginAttendance(restart=false){if(account!=='teacher')return;if(restart||!attendanceDraft||attendanceDraftDate!==isoDay()){attendanceDraftDate=isoDay();attendanceDraft=Object.fromEntries(roster.map(r=>[r.id,!restart&&db.attendanceSavedDate===isoDay()?db.attendance[r.id]||'Présent':'Présent']));attendanceStarted=Date.now();attendanceSearch='';}if(restart)render()}
function attendanceList(){return roster.filter(r=>r.name.toLowerCase().includes(attendanceSearch.toLowerCase())).map(r=>{const status=attendanceDraft[r.id];return `<div class="attendance-person"><div><b>${esc(r.name)}</b><small>${status}</small></div><div class="attendance-taps">${['Absent','En retard'].map(v=>`<button class="${status===v?'selected':''}" aria-label="${esc(r.name)} : ${v}" aria-pressed="${status===v}" onclick="recordAttendance('${r.id}','${v}')">${v==='Absent'?'Absent':'Retard'}</button>`).join('')}</div></div>`}).join('')||'<p>Aucun élève trouvé.</p>'}
function attendanceClass(){beginAttendance();const absent=Object.values(attendanceDraft).filter(v=>v==='Absent').length,late=Object.values(attendanceDraft).filter(v=>v==='En retard').length;return head('Faire l’appel','CM2 A · '+displayDay(isoDay())+' · 60 élèves')+`<section class="card"><p>Tout le monde est présent par défaut. Touchez uniquement les absents ou les retards. Touchez à nouveau pour remettre présent.</p><div class="attendance-summary"><b>${60-absent-late} présents</b><span>${absent} absents</span><span>${late} retards</span></div><label>Rechercher un élève<input type="search" value="${esc(attendanceSearch)}" oninput="attendanceSearch=this.value;document.querySelector('#attendance-list').innerHTML=attendanceList()"></label><div id="attendance-list">${attendanceList()}</div><div class="attendance-save"><button class="primary" onclick="saveAttendance()">Enregistrer · 60 élèves</button><button onclick="markAllPresent()">Tous présents</button>${facilitator?'<button onclick="beginAttendance(true)">Recommencer le test chronométré</button>':''}</div>${facilitator?'<p class="help">Chronométrage du premier affichage à l’enregistrement. Mesure mécanique, pas un résultat terrain. Dernier essai : '+(db.attendanceTrialSeconds??'non mesuré')+' secondes.</p>':''}</section>`}
function recordAttendance(id,v){if(account!=='teacher'||!roster.some(r=>r.id===id)||!['Présent','Absent','En retard'].includes(v))return;beginAttendance();attendanceDraft[id]=attendanceDraft[id]===v?'Présent':v;render()}
function markAllPresent(){if(account!=='teacher')return;beginAttendance();roster.forEach(r=>attendanceDraft[r.id]='Présent');render();notify('60 élèves présents dans le brouillon. Enregistrez pour confirmer.')}
function saveAttendance(){if(account!=='teacher')return;beginAttendance();db.attendance={...attendanceDraft};db.attendanceSavedDate=attendanceDraftDate;db.attendanceTrialSeconds=Math.max(0,Math.round((Date.now()-attendanceStarted)/1000));log('Appel CM2 enregistré : 60 élèves');render();notify('Appel enregistré. La direction peut le consulter.')}
function justifyAbsence(){if(account!=='parent')return;modal(`<h2>Justifier une absence</h2><p>Ibrahima · ${displayDay(isoDay(-2))}, 8 h à 10 h</p><form onsubmit="submitAbsence(event)"><label>Motif<select id="absence-reason">${['Rendez-vous médical','Transport ou intempéries','Motif familial','Autre'].map(v=>`<option ${db.absence.reason===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Précisions facultatives<textarea id="absence-note" maxlength="1500">${esc(db.absence.note)}</textarea></label><p class="help">N’ajoutez aucune donnée médicale réelle dans la démonstration.</p>${fieldsEnd('Transmettre au surveillant général')}</form>`)}function submitAbsence(e){e.preventDefault();if(account!=='parent')return;db.absence={status:'Transmise',reason:$('#absence-reason').value,note:$('#absence-note').value};log('Justification reçue pour Ibrahima');closeModal();render();notify('Justification transmise. Ouvrez le compte direction pour la valider.')}function validateAbsence(valid){if(account!=='admin')return;db.absence.status=valid?'Justifiée':'Précision demandée';log(valid?'Absence de Ibrahima justifiée par la direction':'Précision demandée sur la justification');render();notify('Le statut est maintenant visible dans le compte parent.')}
function balance(){return Math.max(0,90000-db.payments.reduce((s,p)=>s+p.amount,0))}function balanceStudent(id){return Math.max(0,45000-db.payments.filter(p=>p.student===id).reduce((s,p)=>s+p.amount,0))}
function finance(){return head(account==='admin'?'Scolarité et encaissements':'Frais de scolarité','Famille Fall · Échéances, versements partiels et reçus.')+stats([['Facturé','90 000 F CFA','2 enfants'],['Réglé',money(90000-balance()),'Versements simulés'],['À régler',money(balance()),'Échéance : '+displayDay(isoDay(6))],['Paiements',String(db.payments.length),'Reçus disponibles']])+card('Échéances',`<div class="table-wrap"><table><thead><tr><th>Élève</th><th>Période</th><th>Solde</th><th>Statut</th></tr></thead><tbody>${Object.entries(students).map(([id,s])=>`<tr><td>${s.short} · ${s.class}</td><td>${new Intl.DateTimeFormat('fr-SN',{month:'long'}).format(new Date())}</td><td>${money(balanceStudent(id))}</td><td><span class="tag ${balanceStudent(id)?'amber':''}">${balanceStudent(id)?'À régler':'Réglé'}</span></td></tr>`).join('')}</tbody></table></div><div class="toolbar"><button class="primary" onclick="paymentModal()" ${balance()===0?'disabled':''}>${account==='admin'?'Enregistrer un versement simulé':'Simuler un paiement'}</button></div><p class="help">Wave, Orange Money et espèces : aucune transaction réelle. Les reçus sont sans valeur comptable.</p>`)+card('Historique des versements',db.payments.map(p=>`<div class="row"><div class="body"><h3>${money(p.amount)} · ${students[p.student].short}</h3><div class="meta">${p.date} · ${esc(p.method)} · ${p.id}</div></div><button class="small" onclick="receipt('${p.id}')">Reçu</button></div>`).join(''))}
function paymentModal(){if(!permitted('parent','admin'))return;modal(`<h2>Versement de démonstration</h2><span class="tag amber">Aucun débit réel</span><form onsubmit="submitPayment(event)"><label>Élève<select id="pay-student" onchange="updatePayMax()">${Object.entries(students).filter(([id])=>balanceStudent(id)>0).map(([id,s])=>`<option value="${id}">${s.name} · Solde ${money(balanceStudent(id))}</option>`).join('')}</select></label><label>Montant en F CFA<input id="pay-amount" type="number" min="1" step="1" required></label><label>Moyen<select id="pay-method"><option>Wave</option><option>Orange Money</option>${account==='admin'?'<option>Espèces</option>':''}</select></label><p class="help">Ce parcours ne demande aucun numéro de carte, code secret ou identifiant de portefeuille.</p>${fieldsEnd('Confirmer la simulation')}</form>`);updatePayMax()}function updatePayMax(){const n=balanceStudent($('#pay-student').value);$('#pay-amount').max=n;$('#pay-amount').value=n}function submitPayment(e){e.preventDefault();if(!permitted('parent','admin'))return;const id=$('#pay-student').value,n=Number($('#pay-amount').value);if(!Number.isInteger(n)||n<=0||n>balanceStudent(id)){notify('Choisissez un montant valide dans la limite du solde.');return}db.payments.push({id:'DEMO-'+String(db.payments.length+1).padStart(3,'0'),student:id,amount:n,method:$('#pay-method').value,date:'À l’instant'});log('Versement fictif de '+money(n)+' pour '+students[id].short);closeModal();render();notify('Versement simulé enregistré. Le solde a été actualisé.')}
function receipt(id){const p=db.payments.find(p=>p.id===id);if(!p||!permitted('parent','admin'))return;modal(`<span class="tag amber">Sans valeur comptable</span><h2 style="margin-top:15px">Reçu ${p.id}</h2><p>${students[p.student].name} · ${students[p.student].class}</p><h2>${money(p.amount)}</h2><p>Moyen : ${esc(p.method)}<br>Date : ${esc(p.date)}</p><button class="primary" onclick="downloadReceipt('${p.id}')">Télécharger le reçu fictif</button><div class="actions"><button onclick="closeModal()">Fermer</button></div>`)}function downloadReceipt(id){let p=db.payments.find(p=>p.id===id);download('Recu_'+p.id+'.txt',`REÇU DE DÉMONSTRATION, SANS VALEUR COMPTABLE\nGroupe scolaire pilote Malika Plage, établissement fictif\n${p.id}\nÉlève : ${students[p.student].name}\nMontant : ${money(p.amount)}\nMoyen : ${p.method}\nAucune transaction réelle.`)}
function documents(){const ids=account==='student'?['ibrahima']:child==='all'?['awa','ibrahima']:[child];return head(account==='student'?'Mes documents':'Documents de mes enfants','Des documents organisés et des ressources à télécharger.')+(account==='parent'?children():'')+ids.map(id=>card(nameTarget(id),`<div class="document"><div class="file-icon">TXT</div><div class="body"><h3>Bulletin de démonstration</h3><div class="meta">${students[id].name} · Aucune note réelle</div></div><button class="small" onclick="downloadBulletin('${id}')">Télécharger</button></div>${db.homework.filter(h=>h.student===id).map(h=>`<div class="document"><div class="file-icon">TXT</div><div class="body"><h3>${esc(h.title)}</h3><div class="meta">${esc(h.subject)} · Pour le ${esc(h.due)}</div></div><button class="small" onclick="downloadTask('${h.id}')">Fiche</button></div>`).join('')}`)).join('')}
function downloadBulletin(id){if(account==='student'&&id!=='ibrahima')return;download('Bulletin_'+id+'_demo.txt','BULLETIN FICTIF\n'+students[id].name+' · '+students[id].class+'\nAucune note réelle. Présentation destinée aux tests de prototype.');notify('Document fictif téléchargé.')}function download(n,t){const b=new Blob([t],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function forms(){const staff=permitted('admin','teacher');return head(staff?'Formulaires et réponses':'Autorisations et formulaires',staff?'Préparez les demandes et consultez les réponses des responsables.':'Consultez la demande avant de donner votre réponse.',staff?'<button class="primary small" onclick="newForm()">+ Créer</button>':'')+db.forms.map(f=>card(esc(f.title),`<span class="tag blue">${nameTarget(f.student)}</span><p>${esc(f.body)}</p><div class="meta">Réponse avant le ${esc(f.deadline)}</div><div class="row"><div><span class="tag ${db.responses[f.id]?'':'amber'}">${db.responses[f.id]?esc(db.responses[f.id].choice):'Réponse attendue'}</span>${db.responses[f.id]?'<p class="help">Responsable : Fatou Fall · '+esc(db.responses[f.id].note||'Sans commentaire')+'</p>':''}</div>${staff?'':`<button class="primary small" onclick="answerForm('${f.id}')">${db.responses[f.id]?'Modifier ma réponse':'Répondre'}</button>`}</div>${staff?'<p class="help">Échantillon : une famille. Les réponses des autres élèves ne sont pas simulées.</p>':''}`)).join('')}
function answerForm(id){if(account!=='parent')return;const f=db.forms.find(x=>x.id===id),r=db.responses[id];modal(`<h2>${esc(f.title)}</h2><p>${esc(f.body)}</p><form onsubmit="submitForm(event,'${id}')"><label>Votre réponse<select id="form-choice"><option ${r?.choice==='J’autorise'?'selected':''}>J’autorise</option><option ${r?.choice==='Je n’autorise pas'?'selected':''}>Je n’autorise pas</option><option ${r?.choice==='Je souhaite être contacté'?'selected':''}>Je souhaite être contacté</option></select></label><label>Commentaire<textarea id="form-note" maxlength="1200">${esc(r?.note||'')}</textarea></label><label class="checkline"><input id="form-confirm" type="checkbox" required> Je confirme avoir lu la demande</label><p class="help">Réponse de démonstration, sans signature juridique réelle.</p>${fieldsEnd('Transmettre ma réponse')}</form>`)}function submitForm(e,id){e.preventDefault();if(account!=='parent')return;db.responses[id]={choice:$('#form-choice').value,note:$('#form-note').value};log('Réponse du parent au formulaire : '+db.forms.find(f=>f.id===id).title);closeModal();render();notify('Réponse transmise, visible par l’enseignante et la direction.')}
function newForm(){if(!permitted('teacher','admin'))return;modal(`<h2>Créer un formulaire</h2><form onsubmit="saveForm(event)"><label>Titre<input id="form-title" required maxlength="150"></label><label>Classe<select id="form-student"><option value="awa">CM2 A</option>${account==='admin'?'<option value="ibrahima">4e A</option>':''}</select></label><label>Date limite<input id="form-deadline" type="date" value="2026-10-20" required></label><label>Description<textarea id="form-body" required></textarea></label>${fieldsEnd('Publier le formulaire')}</form>`)}function saveForm(e){e.preventDefault();if(!permitted('admin','teacher'))return;db.forms.unshift({id:'f'+Date.now(),title:$('#form-title').value,student:$('#form-student').value,deadline:$('#form-deadline').value,body:$('#form-body').value});log('Formulaire publié : '+$('#form-title').value);closeModal();render();notify('Formulaire disponible dans le compte parent.')}
function eventRows(){return [[0,'Fermeture exceptionnelle','Toute l’école'],[3,'Rencontre parents et enseignants',db.booking?'Votre créneau : '+db.booking:'CM2 A'],[6,'Mensualité scolaire','Famille Fall']].map(([offset,t,s])=>{const d=new Date(isoDay(offset)+'T12:00:00Z');const month=new Intl.DateTimeFormat('fr-SN',{month:'short'}).format(d);return `<div class="row"><div class="datebox">${month}<strong>${d.getUTCDate()}</strong></div><div class="body"><h3>${t}</h3><div class="meta">${s}</div></div></div>`}).join('')}
function calendar(){return head('Mon calendrier','Événements et rendez-vous de la communauté scolaire.')+`<div class="grid equal">${card(new Intl.DateTimeFormat('fr-SN',{month:'long',year:'numeric',timeZone:'Africa/Dakar'}).format(new Date()),eventRows())}${account==='parent'?card('Rendez-vous avec Mme Diop',`<p>${displayDay(isoDay(3))} · 15 minutes · À l’école.</p><div class="tabs">${['09:00','09:30','10:00','10:30'].map(t=>`<button class="${db.booking===t?'active':''}" onclick="bookMeeting('${t}')">${t}</button>`).join('')}</div><div class="notice">${db.booking?'✓ Votre créneau : '+db.booking:'Choisissez un horaire pour réserver dans la démo.'}</div>${db.booking?'<button onclick="cancelMeeting()">Annuler le créneau</button>':''}<p class="help">Aucune réservation extérieure. En production, les places seront vérifiées côté serveur.</p>`):account==='teacher'?card('Rendez-vous des familles',db.booking?`<div class="row"><div><h3>${db.booking} · Fatou Fall</h3><div class="meta">Awa · CM2 A · ${displayDay(isoDay(3))}</div></div><span class="tag">Réservé</span></div>`:'<p class="help">Aucune réservation. Le parent peut choisir un créneau depuis son compte.</p>'):card('À retenir','<p>La direction confirmera la reprise des cours. Consultez les annonces de l’école pour suivre les changements.</p>')}</div>`}function bookMeeting(t){if(account!=='parent')return;db.booking=t;log('Rendez-vous de Fatou Fall réservé à '+t);render();notify('Créneau simulé réservé. Il apparaît dans le compte enseignante.')}function cancelMeeting(){if(account!=='parent')return;db.booking='';log('Rendez-vous de Fatou Fall annulé');render()}
function timetable(){const days=[['Lundi',[['08:00','Mathématiques','M. Ndiaye'],['10:00','Français','Mme Sarr'],['14:00','Histoire','M. Ba']]],['Mardi',[['08:00','SVT','Mme Sow'],['10:00','Anglais','M. Kane'],['14:00','Mathématiques','M. Ndiaye']]],['Mercredi',[['08:00','Français','Mme Sarr'],['10:00','Physique','M. Diouf']]],['Jeudi',[['08:00','Mathématiques','M. Ndiaye'],['10:00','Géographie','M. Ba'],['14:00','Anglais','M. Kane']]],['Vendredi',[['08:00','SVT','Mme Sow'],['10:00','Français','Mme Sarr']]]];return head('Mon emploi du temps','Ibrahima · 4e A · Semaine type de démonstration.')+card('Planning hebdomadaire',`<div class="table-wrap"><div class="week">${days.map(([d,ls])=>`<div class="day"><h3>${d}</h3>${ls.map(([t,m,n])=>`<div class="lesson"><b>${m}</b><small>${t} · 2 heures</small><small>${n}</small></div>`).join('')}</div>`).join('')}</div></div><div class="notice amber">Ce planning fictif illustre la structure. La fermeture exceptionnelle du 14 octobre prime sur le planning habituel.</div>`)}
function community(){return head('Élèves et responsables','Séparez les contacts d’urgence, les responsables scolaires et les payeurs.','<button class="primary small" onclick="newContact()">+ Responsable</button>')+card('Responsables de la famille Fall',`<div class="toolbar"><input id="contact-search" type="search" placeholder="Rechercher un responsable" aria-label="Rechercher un responsable" oninput="filterContacts()"></div><div id="contacts">${contactRows()}</div>`)+card('Outils de démarrage',`<div class="pillrow"><button onclick="downloadImportTemplate()">Modèle d’import CSV</button><button onclick="showImport()">Importer un échantillon</button><button onclick="exportDirectory()">Exporter la liste fictive</button></div><p class="help">Numéros de démonstration. Un import de production vérifiera les matricules, doublons et autorisations avant toute écriture.</p>`)}
function contactRows(q=''){return db.contacts.filter(c=>(c.name+' '+c.relationship).toLowerCase().includes(q.toLowerCase())).map(c=>`<div class="row start">${avatar(c.name.split(' ').map(x=>x[0]).join('').slice(0,2))}<div class="body"><h3>${esc(c.name)}</h3><span class="tag ${c.relationship==='Payeur'?'amber':''}">${esc(c.relationship)}</span><p class="meta">${esc(c.student)} · ${esc(c.phone)}</p><p class="help">${esc(c.access)}</p></div><button class="small" onclick="editContact('${c.id}')">Modifier</button></div>`).join('')||'<p class="empty">Aucun résultat.</p>'}function filterContacts(){$('#contacts').innerHTML=contactRows($('#contact-search').value)}function newContact(){editContact('new')}function editContact(id){if(account!=='admin')return;const c=db.contacts.find(c=>c.id===id)||{};modal(`<h2>${id==='new'?'Ajouter un responsable':'Modifier le responsable'}</h2><form onsubmit="saveContact(event,'${id}')"><label>Nom<input id="contact-name" required value="${esc(c.name||'')}"></label><label>Téléphone de démonstration<input id="contact-phone" required value="${esc(c.phone||'+221 77 000 00 03')}"></label><label>Relation<select id="contact-relation">${['Parent autorisé','Tuteur autorisé','Payeur','Contact d’urgence'].map(v=>`<option ${c.relationship===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Élève concerné<select id="contact-student">${['Awa et Ibrahima','Awa','Ibrahima'].map(v=>`<option ${c.student===v?'selected':''}>${v}</option>`).join('')}</select></label><p class="help">Utilisez uniquement des données fictives. En production, la relation et les droits seront vérifiés avec l’établissement.</p>${fieldsEnd('Enregistrer')}</form>`)}function saveContact(e,id){e.preventDefault();if(account!=='admin')return;const r=$('#contact-relation').value,c={id:id==='new'?'c'+Date.now():id,name:$('#contact-name').value,phone:$('#contact-phone').value,relationship:r,student:$('#contact-student').value,access:r==='Payeur'?'Frais et reçus uniquement':r==='Contact d’urgence'?'Contact en cas d’urgence, sans dossier scolaire':'Suivi scolaire et frais'};let index=db.contacts.findIndex(x=>x.id===id);if(index===-1)db.contacts.push(c);else db.contacts[index]=c;log('Responsable fictif enregistré : '+c.name);closeModal();render();notify('Contact enregistré dans la démonstration.')}
function downloadImportTemplate(){download('Modele_eleves.csv','matricule,nom,classe,annee,nom_responsable,telephone,relation\nDEMO-001,Awa Fall,CM2 A,2026-2027,Fatou Fall,+221770000001,Parent autorisé')}function exportDirectory(){download('Responsables_demo.csv','\uFEFF'+[['Nom','Relation','Élèves','Téléphone','Accès'],...db.contacts.map(c=>[c.name,c.relationship,c.student,c.phone,c.access])].map(r=>r.map(c=>'"'+c.replaceAll('"','""')+'"').join(',')).join('\n'))}function showImport(){modal(`<h2>Importer un échantillon fictif</h2><p>Un responsable fictif pour Awa sera ajouté : Aminata Fall, contact d’urgence.</p><div class="notice">Vérification démo : nom présent, relation choisie, téléphone fictif. Aucun dossier ou fichier personnel.</div><div class="actions"><button onclick="closeModal()">Annuler</button><button class="primary" onclick="importSample()">Confirmer l’import démo</button></div>`)}function importSample(){if(account!=='admin')return;if(!db.contacts.some(c=>c.id==='sample'))db.contacts.push({id:'sample',name:'Aminata Fall',relationship:'Contact d’urgence',student:'Awa',phone:'+221 77 000 00 04',access:'Contact d’urgence, sans accès au dossier scolaire'});log('Échantillon fictif importé');closeModal();render();notify('Échantillon ajouté, sans doublon.')}
function activityRows(n=50){return db.activities.slice(0,n).map(a=>`<div class="row start"><span class="activity-dot" style="margin-top:7px"></span><div class="body"><p>${esc(a.text)}</p><div class="meta">${esc(a.author)} · ${a.date}</div></div></div>`).join('')||'<p class="empty">Aucune action pour le moment. Testez un parcours parent ou enseignant.</p>'}function activity(){return head('Activité de la démonstration','Retrouvez les actions effectuées depuis les différents comptes.')+card('Historique local',activityRows())+'<p class="help">Cet historique de navigateur illustre la traçabilité. Il ne constitue pas un journal de sécurité de production.</p>'}
function preferences(){const p=db.preferences[account];return head('Mon profil et mes préférences','Des notifications utiles, à votre rythme.')+`<div class="grid equal">${card('Profil de démonstration',`<div class="profile-card">${avatar(roles[account].initials)}<div><h3>${roles[account].name}</h3><div class="meta">${roles[account].detail}</div></div></div><p class="help">Votre compte est fictif. La connexion réelle sera intégrée après validation du pilote.</p><button onclick="logout()">Changer de compte</button>`)}${card('Notifications',`<form onsubmit="savePreferences(event)"><label>Canal préféré<select id="pref-channel">${['Application','WhatsApp','SMS','E-mail'].map(v=>`<option ${p.channel===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="checkline"><input id="pref-digest" type="checkbox" ${p.digest?'checked':''}> Résumé quotidien pour les annonces ordinaires</label><label class="checkline"><input id="pref-quiet" type="checkbox" ${p.quiet?'checked':''}> Limiter les interruptions en dehors des horaires</label><div class="notice">Les alertes prioritaires suivront la politique de l’école. Aucun canal extérieur connecté ici.</div><button class="primary">Enregistrer mes préférences</button></form>`)}</div>`+card('Langues et confidentialité','<p>Interface française. Les besoins en Wolof, Pulaar et annonces audio seront mesurés auprès des écoles pilotes.</p><p class="help">Pour les téléphones partagés : prévoir déconnexion, aperçus masqués et récupération assistée. Ne saisissez aucune information réelle dans ce prototype.</p><button class="danger small" onclick="resetDemo()">Réinitialiser toutes les données fictives</button>')}
function savePreferences(e){e.preventDefault();db.preferences[account]={channel:$('#pref-channel').value,digest:$('#pref-digest').checked,quiet:$('#pref-quiet').checked};persist();notify('Préférences enregistrées pour ce compte de démonstration.')}
function project(){return '<div class="notice"><span class="doc-internal">Économie du projet : calculateur et guide commercial · document interne</span></div>'+head('Projet & pilote','Cahier des charges et validation terrain du projet Sénégal.')+hero('Version de travail','Tester les usages avant le déploiement','Une famille fictive, une classe et quatre comptes pour explorer les parcours.','Guide des entretiens',"notify('Guide pilote : document interne, non publié en ligne.')")+`<div class="grid equal">${card('Livrables du projet',`<div class="document"><div class="file-icon">CSV</div><div class="body"><h3>Backlog priorisé</h3><div class="meta">P0 : fondations · P1 : intégrations · P2 : extensions</div></div><span class="doc-internal">Document interne</span></div><div class="document"><div class="file-icon">TXT</div><div class="body"><h3>Guide pilote</h3><div class="meta">Entretiens, tâches et critères de décision</div></div><span class="doc-internal">Document interne</span></div><p>Nom ÉcoleLien provisoire, disponibilité commerciale non vérifiée.</p>`)}${card('Parcours à tester','<ol><li>Parent : confirmer la fermeture.</li><li>Parent : justifier l’absence; direction : valider.</li><li>Enseignante : publier un devoir; parent : consulter.</li><li>Parent : envoyer un message; enseignante : répondre.</li><li>Enseignante : publier un formulaire; parent : répondre.</li><li>Parent : simuler un versement; direction : consulter le reçu.</li><li>Élève : consulter son planning et télécharger sa fiche.</li></ol>')}</div>`+card('Ce qui est prévu avant un vrai pilote','<p>Authentification réelle, permissions côté serveur, séparation des écoles, conservation sécurisée, synchronisation entre appareils et intégrations validées.</p><p>Revue locale de protection des données et des transferts avant de collecter des dossiers réels. Les comptes présents illustrent les parcours; ils ne protègent pas des données de production.</p>')+card('Mesurer avec les écoles','<p>Échantillon proposé : 15 parents, 15 élèves, 8 enseignants et 4 responsables dans 2 à 3 écoles privées. Compléter par des entretiens publics et hors Dakar avant de généraliser.</p><p>Cibles proposées : 80 % des tâches réussies sans aide, 90 % des contacts valides après nettoyage, réduction de 25 % du temps de relance. Ces valeurs sont des objectifs, pas des résultats.</p>')+card('Sources de conception',`<div class="row"><a href="https://www.parentsquare.com/platform/studentsquare/" target="_blank" rel="noopener">ParentSquare : workflows StudentSquare ↗</a></div><div class="row"><a href="https://play.google.com/store/apps/details?id=com.parentsquare.studentsquare" target="_blank" rel="noopener">StudentSquare : avis utilisateurs ↗</a></div><div class="row"><a href="https://play.google.com/store/apps/details?id=com.ousmane.samaschool" target="_blank" rel="noopener">Sama School : retours de navigation ↗</a></div><div class="row"><a href="https://www.education.sn/posts/interdiction-de-lusage-du-telephone-portable-en-milieu-scolaire" target="_blank" rel="noopener">MEN : usage des téléphones en milieu scolaire ↗</a></div><div class="row"><a href="https://www.cdp.sn/conformite/formalites" target="_blank" rel="noopener">CDP : formalités ↗</a></div><p class="help">Avis publics qualitatifs, parfois anciens; besoins locaux à valider. Aucun entretien terrain encore réalisé.</p>`)}
function moreMenu(){modal(`<h2>Mon espace ${roles[account].label.toLowerCase()}</h2><div class="nav" style="margin:0">${navigationPages(account).map(p=>`<button style="color:var(--ink);background:#f0f5ed" onclick="closeModal();go('${p}')">${icons[p]} ${p}</button>`).join('')}</div><div class="actions"><button onclick="closeModal();logout()">Changer de compte</button><button onclick="closeModal()">Fermer</button></div>`)}
function loginScreen(){return `<div class="login"><section class="login-intro"><div class="brand"><span class="mark">◈</span>École<em>Lien</em></div><h1>L’école, les familles.<br>Le même lien.</h1><p>Une information claire. Une action simple. Un espace adapté à chacun, pensé pour le Sénégal.</p><div class="illustration"><div><b>✓</b>Une absence expliquée.<br>Une famille informée.</div><div><b>✎</b>Un devoir retrouvé.<br>Une semaine préparée.</div><div><b>${icon('message')}</b>Un échange utile.<br>Une réponse au bon endroit.</div><div><b>◈</b>Un reçu disponible.<br>Un suivi partagé.</div></div><p class="footnote">Groupe scolaire pilote Malika Plage · Dakar</p></section><section class="login-panel"><span class="tag">PROTOTYPE INTERACTIF</span><h1 style="margin-top:16px">Bienvenue dans votre école.</h1><p class="subtitle">Choisissez un compte pour découvrir son expérience.</p><div class="account-grid">${Object.entries(roles).map(([id,r])=>`<button class="account" onclick="login('${id}')">${avatar(r.initials)}<span class="tag" style="float:right">${r.label}</span><h3>${r.name}</h3><p>${r.intro}</p><span class="arrow">Ouvrir mon espace →</span></button>`).join('')}</div><p class="help" style="margin-top:23px">Connexion de démonstration, sans mot de passe. Données fictives conservées dans ce navigateur. Aucun message envoyé ni paiement débité.</p><button class="ghost small" onclick="installPrototype()">Installer sur le téléphone</button><button class="ghost small" onclick="resetDemo()">Recommencer la démo</button><button class="ghost small" onclick="toggleFacilitator()">${facilitator?'Quitter le mode facilitateur':'Mode facilitateur'}</button></section></div>`}
const views={'Accueil':home,'Actualités':news,'Messages':chats,'Présences':attendance,'Scolarité':finance,'Documents':documents,'Formulaires':forms,'Calendrier':calendar,'Préférences':preferences,'Projet & pilote':project,'Devoirs':homework,'Emploi du temps':timetable,'Ma classe':classroom,'Communauté':community,'Activité':activity};
function render(){if(!roles[account]){$('#root').innerHTML=loginScreen();return}const r=roles[account];if(!r.pages.includes(page))page='Accueil';const nav=navigationPages(account).map(p=>`<button class="${page===p?'active':''}" onclick="go('${p}')"><span>${icons[p]}</span>${p}</button>`).join(''),bottom=account==='parent'?['Accueil','Notes','Messages','Scolarité']:account==='student'?['Accueil','Notes','Devoirs','Messages']:account==='teacher'?['Accueil','Présences','Devoirs','Messages']:['Accueil','Communauté','Présences','Scolarité'];$('#root').innerHTML=`<aside><div class="brand"><span class="mark">◈</span>École<em>Lien</em></div><div class="school">GROUPE SCOLAIRE PILOTE MALIKA PLAGE<br><p>Dakar · Sénégal · 2026 / 2027</p></div><nav class="nav" aria-label="Navigation principale">${nav}</nav><div class="aside-foot"><p>Votre espace ${r.label.toLowerCase()}</p><button class="small" onclick="logout()">Changer de compte ↗</button></div></aside><main class="main"><header class="top"><div class="top-left">Groupe scolaire pilote Malika Plage<br><b>Année scolaire 2026 / 2027</b></div><div class="top-right"><button class="ghost" onclick="go('Préférences')" aria-label="Préférences">${icon('settings')}</button><div class="identity">${avatar(r.initials)}<div><b>${r.name}</b><small>${r.label}</small></div></div><button class="ghost" onclick="logout()">Changer</button></div></header><div class="demo compact-strip">Groupe scolaire pilote Malika Plage · Données fictives · Aucun envoi ni débit réel</div><div class="content">${views[page]()}</div></main><nav class="bottom-nav" aria-label="Navigation mobile">${bottom.map(p=>`<button class="${page===p?'active':''}" onclick="go('${p}')"><span>${icons[p]}</span>${p==='Emploi du temps'?'Planning':p}</button>`).join('')}<button onclick="moreMenu()"><span>${icon('menu')}</span>Plus</button></nav>`}
render();
const selectedPlatform=new URLSearchParams(location.search).get('platform');
if(['ios','android'].includes(selectedPlatform)){
 document.body.dataset.platform=selectedPlatform;
 const status=document.createElement('div');status.className='statusbar';status.innerHTML='<span>9:41</span><span class="camera"></span><span>▂▅▇  ▰</span>';document.body.appendChild(status);
 const gesture=document.createElement('div');gesture.className='gesture';document.body.appendChild(gesture);
}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==window.parent)return;const data=event.data;if(data?.type==='ecolelien-demo-account'&&roles[data.role])login(data.role)});
// Academic records and child-first navigation.
let academicStudent=account==='student'?'ibrahima':'awa',activeSubject=null;
const subjects={awa:[{id:'alc',name:'Langue et communication',teacher:'Marième Diop',coefficient:1,max:10,color:'#2d6c5f',marks:[{id:'af1',title:'Lecture et compréhension',type:'Devoir',score:8.5,max:10,weight:1,date:'2026-10-21',description:'Lire un texte et répondre aux questions de compréhension.'},{id:'af2',title:'Production d’écrit',type:'Devoir',score:7,max:10,weight:1,date:'2026-10-28',description:'Rédiger un court récit à partir d’une série d’images.'}]},{id:'amath',name:'Mathématiques',teacher:'Marième Diop',coefficient:1,max:10,color:'#177dac',marks:[{id:'am1',title:'Fractions simples',type:'Devoir',score:8,max:10,weight:1,date:'2026-10-22',description:'Comparer et additionner des fractions de même dénominateur.'},{id:'am2',title:'Résolution de problèmes',type:'Devoir',score:7,max:10,weight:1,date:'2026-10-29',description:'Résoudre deux problèmes et expliquer la démarche.'}]},{id:'aesvs',name:'Éducation à la science et à la vie sociale',teacher:'Marième Diop',coefficient:1,max:10,color:'#427d52',marks:[{id:'as1',title:'Les plantes',type:'Interrogation',score:7.5,max:10,weight:1,date:'2026-10-23',description:'Identifier les parties d’une plante et leurs fonctions.'},{id:'ah1',title:'Les régions du Sénégal',type:'Devoir',score:6.5,max:10,weight:1,date:'2026-10-30',description:'Situer les 14 régions sur une carte de démonstration.'}]},{id:'aepsa',name:'Éducation physique, sportive et artistique',teacher:'Marième Diop',coefficient:1,max:10,color:'#bf752e',marks:[{id:'ae1',title:'Course et relais',type:'Évaluation pratique',score:8,max:10,weight:1,date:'2026-10-24',description:'Course de vitesse et passage du témoin.'}]}],ibrahima:[{id:'imath',name:'Mathématiques',teacher:'M. Ndiaye',coefficient:4,color:'#16809c',marks:[{id:'im1',title:'Équations du premier degré',type:'Devoir',score:14,weight:1,date:'2026-10-22',description:'Résoudre des équations et vérifier les solutions.'},{id:'im2',title:'Calcul littéral',type:'Devoir',score:12,weight:2,date:'2026-10-27',description:'Développer et réduire des expressions algébriques.'}]},{id:'ifr',name:'Français',teacher:'Mme Sarr',coefficient:3,color:'#2f6a5e',marks:[{id:'if1',title:'Résumé de texte',type:'Devoir',score:15,weight:1,date:'2026-10-23',description:'Rédiger un résumé structuré de 10 lignes.'}]},{id:'ien',name:'Anglais',teacher:'M. Kane',coefficient:2,color:'#35645a',marks:[{id:'ie1',title:'Reading comprehension',type:'Interrogation',score:16,weight:1,date:'2026-10-21',description:'Read the paragraph and answer the questions.'}]},{id:'isvt',name:'SVT',teacher:'Mme Sow',coefficient:2,color:'#4a8250',marks:[{id:'is1',title:'Écosystèmes',type:'Devoir',score:13,weight:1,date:'2026-10-20',description:'Décrire des relations entre organismes et leur milieu.'}]},{id:'iph',name:'Physique et chimie',teacher:'M. Diouf',coefficient:2,color:'#bf572d',marks:[{id:'ip1',title:'Circuit électrique',type:'Devoir',score:9,weight:1,date:'2026-10-28',description:'Identifier un circuit ouvert et un circuit fermé.'}]},{id:'ihg',name:'Histoire et géographie',teacher:'M. Ba',coefficient:2,color:'#b5922b',marks:[{id:'ih1',title:'Repères et cartes',type:'Devoir',score:17,weight:1,date:'2026-10-29',description:'Lire et interpréter une carte géographique.'}]}]};
if(!db.academics){db.academics=subjects;persist()}if(!db.academicPreferences)db.academicPreferences={threshold:10,reminder:2};
function subjectAverage(s){let total=s.marks.reduce((t,m)=>t+m.score*m.weight,0),weight=s.marks.reduce((t,m)=>t+m.weight,0);return weight?total/weight:null}function overallAverage(id){const ss=db.academics[id],weight=ss.reduce((t,s)=>t+s.coefficient,0);return ss.reduce((t,s)=>t+subjectAverage(s)*s.coefficient,0)/weight}function decimal(n){return n===null?'Non évalué':Number(n.toFixed(2)).toString().replace('.',',')}
for(const role of ['parent','student','teacher','admin']){roles[role].pages.splice(1,0,'Notes','Bulletin','Profil élève')};icons.Notes=icon('grade');icons.Bulletin=icon('file');icons['Profil élève']=icon('users');
const earlierLogin=login;login=function(r){earlierLogin(r);academicStudent=r==='student'?'ibrahima':'awa';activeSubject=null;render()};
function selectAcademic(id,p='Notes'){if(account==='student'&&id!=='ibrahima')return;if(account==='teacher'&&id!=='awa')return;academicStudent=id;activeSubject=null;child=id;go(p)}
function academicPicker(){if(account==='student'||account==='teacher')return '';return `<div class="academic-bar"><select aria-label="Élève du dossier" onchange="academicStudent=this.value;activeSubject=null;render()">${Object.entries(students).map(([id,s])=>`<option value="${id}" ${academicStudent===id?'selected':''}>${s.name} · ${s.class}</option>`).join('')}</select><select aria-label="Période scolaire"><option>${firstPeriod(academicStudent)} · Démo</option></select></div>`}
function childCard(id){let s=students[id];return `<section class="student-card"><div class="profile-card">${avatar(s.initials)}<div><h2>${s.name}</h2><p>Groupe scolaire pilote Malika Plage</p><p>${s.class} · Matricule DEMO-${id==='awa'?'001':'002'}</p></div></div><div class="vue-summary"><span>Moyenne indicative</span><b>${decimal(overallAverage(id))} / ${gradeMax(id)}</b></div><div class="student-modules">${[['Notes','A⁺','Notes'],['Devoirs','✎',account==='student'||account==='teacher'?'Devoirs':'Documents'],['Présences','✓','Présences'],['Planning','▦',account==='student'?'Emploi du temps':'Calendrier'],['Bulletin','▤','Bulletin'],['Dossier','♧','Profil élève']].filter(x=>roles[account].pages.includes(x[2])).map(([t,i,p])=>`<button class="${t==='Notes'?'grades':''}" onclick="selectAcademic('${id}','${p}')"><span>${symbolIcon(i)}</span>${t}</button>`).join('')}</div></section>`}
function grades(){if(account==='student')academicStudent='ibrahima';if(account==='teacher')academicStudent='awa';const id=academicStudent,s=students[id],ss=db.academics[id];if(activeSubject){const sub=ss.find(x=>x.id===activeSubject);if(!sub){activeSubject=null;return grades()}return head(sub.name,s.name+' · '+s.class)+`<button class="return-link" onclick="activeSubject=null;render()">‹ Toutes les matières</button><div class="course-hero" style="background:${sub.color}"><span>${firstPeriod(academicStudent)} · Moyenne de démonstration</span><strong>${decimal(subjectAverage(sub))} <small style="font-size:18px">/ ${sub.max||20}</small></strong><p>${sub.teacher} · Coefficient de matière : ${sub.coefficient}</p></div>`+card('Évaluations et consignes',sub.marks.map(m=>`<button class="grade-row" onclick="gradeDetail('${sub.id}','${m.id}')"><div class="body"><span class="tag ${m.type==='Composition'?'blue':'amber'}">${esc(m.type)}</span><h3 style="margin-top:9px">${esc(m.title)}</h3><div class="meta">${m.date} · Poids dans la matière : ${m.weight}</div></div><span class="score ${m.score<(m.max||20)/2?'low':''}">${decimal(m.score)} / ${m.max||20} ›</span></button>`).join(''))+`<div class="vue-note">Calcul illustratif : notes pondérées par le poids de chaque évaluation. Les règles seront configurées et validées par chaque établissement.</div>`}
return head('Notes et évaluations',s.name+' · '+s.class,account==='teacher'?'<button class="primary small" onclick="newGrade()">+ Note</button>':'')+academicPicker()+`<div class="vue-summary"><span>${firstPeriod(id)} · Moyenne indicative</span><b>${decimal(overallAverage(id))} / ${gradeMax(id)}</b></div><div class="subject-grid">${ss.map(sub=>`<button class="subject-tile" style="background:${sub.color}" onclick="activeSubject='${sub.id}';render()"><h3>${sub.name}</h3><span class="coefficient">Coef. ${sub.coefficient}</span><strong>${decimal(subjectAverage(sub))}<small> / ${sub.max||20}</small></strong><div class="subject-teacher">${sub.teacher} · ${sub.marks.length} évaluation${sub.marks.length>1?'s':''}</div></button>`).join('')}</div><div class="vue-note">Touchez une matière pour voir ses évaluations, catégories, dates et consignes. Les notes affichées sont fictives.</div>`}
function gradeDetail(subid,mid){const s=db.academics[academicStudent].find(s=>s.id===subid),m=s.marks.find(m=>m.id===mid);modal(`<span class="tag blue">${m.type}</span><h2 style="margin-top:13px">${esc(m.title)}</h2><h2>${decimal(m.score)} / ${m.max||20}</h2><p>${esc(m.description)}</p><p class="meta">${s.name} · ${m.date}<br>Poids de l’évaluation : ${m.weight}<br>Coefficient de la matière : ${s.coefficient}</p><p class="help">Données fictives, aucun lien avec un dossier scolaire réel.</p><div class="actions"><button onclick="closeModal()">Fermer</button></div>`)}
function newGrade(){if(account!=='teacher')return;modal(`<h2>Ajouter une note · Awa</h2><form onsubmit="saveGrade(event)"><label>Matière<select id="grade-subject">${db.academics.awa.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></label><label>Titre<input id="grade-title" required></label><label>Catégorie<select id="grade-type"><option>Devoir</option><option>Composition</option><option>Interrogation</option></select></label><label>Note sur 20<input id="grade-score" type="number" min="0" max="20" step="0.25" required></label><label>Poids de l’évaluation<input id="grade-weight" type="number" min="1" max="10" value="1" required></label><label>Consignes<textarea id="grade-description" required></textarea></label>${fieldsEnd('Enregistrer la note fictive')}</form>`)}function saveGrade(e){e.preventDefault();if(account!=='teacher')return;const n=Number($('#grade-score').value),w=Number($('#grade-weight').value);if(!Number.isFinite(n)||n<0||n>20||!Number.isInteger(w)||w<1||w>10){notify('Vérifiez la note et le poids.');return}db.academics.awa.find(s=>s.id===$('#grade-subject').value).marks.push({id:'g'+Date.now(),title:$('#grade-title').value,type:$('#grade-type').value,score:n,weight:w,description:$('#grade-description').value,date:isoDay()});log('Note fictive publiée pour Awa');closeModal();render();notify('Note disponible dans le compte parent et le bulletin de démonstration.')}
function reportCard(){if(account==='student')academicStudent='ibrahima';if(account==='teacher')academicStudent='awa';const s=students[academicStudent];return head('Bulletin scolaire',s.name+' · '+s.class)+academicPicker()+card(firstPeriod(academicStudent)+' · Démonstration',`<div class="table-wrap"><table><thead><tr><th>Matière</th><th>Coefficient</th><th>Moyenne / ${gradeMax(academicStudent)}</th></tr></thead><tbody>${db.academics[academicStudent].map(sub=>`<tr><td>${sub.name}</td><td>${sub.coefficient}</td><td><b>${decimal(subjectAverage(sub))}</b></td></tr>`).join('')}</tbody></table></div><div class="vue-summary"><span>Moyenne pondérée indicative</span><b>${decimal(overallAverage(academicStudent))} / ${gradeMax(academicStudent)}</b></div><p><button class="primary" onclick="downloadAcademicReport()">Télécharger le bulletin fictif</button></p><p class="help">Sans visa, sans signature, sans valeur officielle. Coefficients et règles illustratifs à configurer avec chaque école.</p>`)}function downloadAcademicReport(){const id=academicStudent,s=students[id];download('Bulletin_'+id+'_fictif.txt','BULLETIN FICTIF, SANS VALEUR OFFICIELLE\n'+s.name+' · '+s.class+'\n'+firstPeriod(id)+' de démonstration\n\n'+db.academics[id].map(sub=>sub.name+' : '+decimal(subjectAverage(sub))+'/'+(sub.max||20)+' · coefficient '+sub.coefficient).join('\n')+'\nMoyenne indicative : '+decimal(overallAverage(id))+'/'+gradeMax(id)+'\nCalcul et coefficients illustratifs, à valider par l’établissement.')}
function studentProfile(){if(account==='student')academicStudent='ibrahima';if(account==='teacher')academicStudent='awa';let s=students[academicStudent];return head('Profil élève',s.name+' · Dossier de démonstration')+academicPicker()+card('Informations scolaires',`<div class="profile-card">${avatar(s.initials)}<div><h2 style="margin:0">${s.name}</h2><p>${s.class} · Groupe scolaire pilote Malika Plage</p></div></div><div class="profile-grid">${[['Matricule','DEMO-'+(academicStudent==='awa'?'001':'002')],['Établissement','Groupe scolaire pilote Malika Plage · Dakar'],['Classe',s.class],['Année scolaire','2026 / 2027'],['Responsable autorisé','Fatou Fall'],['Contacts','Numéros fictifs gérés par le secrétariat']].map(([k,v])=>`<div class="profile-item"><small>${k}</small><b>${v}</b></div>`).join('')}</div><div class="vue-note" style="margin-top:15px">Les droits des responsables, payeurs et contacts d’urgence seront distincts et vérifiés par l’école avant un vrai déploiement.</div>`)}
views.Notes=grades;views.Bulletin=reportCard;views['Profil élève']=studentProfile;
const earlierRender=render;render=function(){if(!db.academics)db.academics=JSON.parse(JSON.stringify(subjects));earlierRender();document.body.classList.add('vue');document.body.classList.toggle('vue-theme-dark',localStorage.getItem('ecolelien-dark')==='1');if(account){const t=document.querySelector('.top-right');if(t)t.insertAdjacentHTML('afterbegin',`<button class="ghost theme-button" onclick="toggleTheme()" aria-label="Changer le thème">${icon('moon')}</button>`)}};function toggleTheme(){localStorage.setItem('ecolelien-dark',localStorage.getItem('ecolelien-dark')==='1'?'0':'1');render()}
render();